update public.content_variants set body = $json${"type":"multiple_choice","answer":"Promises guaranteed high returns","options":["Promises guaranteed high returns","Registered with CoFTRA","Have a long-term financial plan","Be transparent about risks"],"question":"Which are the signs of crypto fraud?","difficulty":"beginner","explanation":"Guaranteed returns are a major red flag. Legitimate investments always have risks."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Menjanjikan imbal hasil tinggi yang dijamin","options":["Menjanjikan imbal hasil tinggi yang dijamin","Terdaftar di Bappebti","Memiliki rencana keuangan jangka panjang","Transparan tentang risiko"],"question":"Manakah tanda penipuan kripto?","difficulty":"beginner","explanation":"Imbal hasil dijamin adalah red flag utama. Investasi yang sah selalu memiliki risiko."}$json$::jsonb where id = '4996dc20-1864-48a3-a322-da82eb3de5ba';
update public.content_variants set body = $json${"type":"fill_blank","answer":"CoFTRA","question":"Before depositing money to a crypto exchange, check whether the exchange is registered with _____.","difficulty":"beginner","explanation":"Only exchanges registered with CoFTRA may legally carry out crypto asset trading in Indonesia."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"Bappebti","question":"Sebelum menyetor uang ke bursa kripto, periksa apakah bursa tersebut terdaftar di _____.","difficulty":"beginner","explanation":"Hanya bursa yang terdaftar di Bappebti yang boleh menyelenggarakan perdagangan aset kripto secara legal di Indonesia."}$json$::jsonb where id = '4ba2f4ac-c2b1-4c36-8f5e-6086723db159';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Impulse purchases that aren't in the budget","options":["Impulse purchases that aren't in the budget","100% Discount","Negative interest","Automatic savings"],"question":"The most common PayLater pitfalls are...","difficulty":"beginner","explanation":"The ease of checkout means that people often buy items that they don't really need."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Pembelian impulsif yang tidak masuk anggaran","options":["Pembelian impulsif yang tidak masuk anggaran","Diskon 100%","Bunga negatif","Tabungan otomatis"],"question":"Jebakan PayLater yang paling umum adalah...","difficulty":"beginner","explanation":"Kemudahan checkout membuat orang sering membeli barang yang sebenarnya tidak terlalu dibutuhkan."}$json$::jsonb where id = '4c1a5b94-7c15-4a7f-bc7d-189dd13b4bdc';
update public.content_variants set body = $json${"text":"Dina learned that Ethereum allows automated programs called smart contracts. But he also knows that many projects on Ethereum fail, so attractive technology doesn't necessarily mean the price will necessarily rise."}$json$::jsonb, body_id = $json${"text":"Dina mempelajari bahwa Ethereum memungkinkan program otomatis yang disebut smart contract. Tetapi ia juga tahu bahwa banyak proyek di Ethereum gagal, jadi teknologi menarik tidak berarti harganya pasti naik."}$json$::jsonb where id = '4ea2cc08-1c72-4bb9-92d3-913466ad4f55';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Because it can increase skills and income in the future","options":["Because it can increase skills and income in the future","Because you don't need to pay","Because interest is always low","Because it is given by the government"],"question":"Why is education debt sometimes called good debt?","difficulty":"beginner","explanation":"The right education can increase competitiveness and income, so that loans can be paid back from greater income."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Karena bisa meningkatkan keterampilan dan pendapatan di masa depan","options":["Karena bisa meningkatkan keterampilan dan pendapatan di masa depan","Karena tidak perlu dibayar","Karena bunga selalu rendah","Karena diberikan oleh pemerintah"],"question":"Mengapa utang pendidikan kadang disebut utang baik?","difficulty":"beginner","explanation":"Pendidikan yang tepat dapat meningkatkan daya saing dan penghasilan, sehingga pinjamannya bisa dibayar kembali dari pendapatan lebih besar."}$json$::jsonb where id = '5362761d-d3ee-425b-876f-df45c078168b';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Exchanges can be hacked or run into financial problems","options":["Exchanges can be hacked or run into financial problems","The exchange always closes active accounts","Crypto on exchanges cannot be sold","The exchange does not require KYC"],"question":"Why is it advisable not to keep all crypto on exchanges in the long term?","difficulty":"beginner","explanation":"Storing crypto on an exchange means entrusting your assets to a third party, which risks being hacked or going bankrupt."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Bursa bisa diretas atau mengalami masalah keuangan","options":["Bursa bisa diretas atau mengalami masalah keuangan","Bursa selalu menutup akun aktif","Kripto di bursa tidak bisa dijual","Bursa tidak memerlukan KYC"],"question":"Mengapa disarankan tidak menyimpan semua kripto di bursa dalam jangka panjang?","difficulty":"beginner","explanation":"Menyimpan kripto di bursa berarti mempercayakan asetmu kepada pihak ketiga, yang berisiko diretas atau bangkrut."}$json$::jsonb where id = '5b6cc3bc-ea80-4ac3-ba56-02b24dc4ac0f';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"P2P transactions with strangers on WhatsApp are safe as long as the price is cheaper.","difficulty":"beginner","explanation":"Low prices from unknown sellers are a common sign of fraud. Money sent to a personal account is difficult to return."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Transaksi P2P dengan orang asing di WhatsApp aman selama harganya lebih murah.","difficulty":"beginner","explanation":"Harga murah dari penjual tidak dikenal adalah tanda umum penipuan. Uang yang terkirim ke rekening pribadi sulit dikembalikan."}$json$::jsonb where id = '5baaaefa-2256-4da4-8d6d-11ef2dfe6922';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"IDR 1,050,000","options":["IDR 1,050,000","IDR 900,000","IDR 150,000","IDR 750,000"],"question":"Bayu bought a headset for IDR 900,000 and was fined IDR 150,000 for late payment. How much does he have to pay in total?","difficulty":"beginner","explanation":"The total cost is the price of the goods plus late fees, not including interest if any."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Rp 1.050.000","options":["Rp 1.050.000","Rp 900.000","Rp 150.000","Rp 750.000"],"question":"Bayu membeli headset Rp 900.000 dan kena denda Rp 150.000 karena telat bayar. Berapa total yang harus ia bayar?","difficulty":"beginner","explanation":"Total biaya adalah harga barang ditambah denda keterlambatan, belum termasuk bunga jika ada."}$json$::jsonb where id = '5f73c963-f6c0-4792-9b8a-6323acf27cf6';
update public.content_variants set body = $json${"type":"fill_blank","answer":"full","question":"To avoid credit card interest, pay the bill _____ every month.","difficulty":"beginner","explanation":"Paying the bill in full before the due date avoids rolling interest."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"penuh","question":"Untuk menghindari bunga kartu kredit, bayar tagihan _____ setiap bulan.","difficulty":"beginner","explanation":"Membayar tagihan penuh sebelum jatuh tempo menghindari bunga bergulir."}$json$::jsonb where id = '62bac762-7486-481f-a066-b2e50ca8d51f';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"It's safe to send money to known crypto sellers via Instagram if the price is cheaper.","difficulty":"beginner","explanation":"Buying from private sellers on social media is high risk. Money can be lost and there is no consumer protection."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Aman mengirim uang ke penjual kripto yang dikenal lewat Instagram jika harganya lebih murah.","difficulty":"beginner","explanation":"Membeli dari penjual pribadi di media sosial berisiko tinggi. Uang bisa hilang dan tidak ada perlindungan konsumen."}$json$::jsonb where id = '6396457b-cb29-4189-b4cd-357aacf893f4';

